INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('eu_law.sparql.select','Query EU legal metadata with a bounded SPARQL SELECT','Query EU legal metadata with a bounded SPARQL SELECT; Query EU publication metadata using bounded SPARQL SELECT or retrieve a CELEX metadata notice. This is metadata, not the full legal text.','legal','{"type":"object","properties":{"query":{"type":"string","description":"Read-only SPARQL SELECT with LIMIT 1..100; no external SERVICE.","minLength":1,"maxLength":8000,"x-parameter-location":"query"}},"required":["query"]}'::jsonb,'{"type":"object","properties":{"data":{"type":"object","properties":{"head":{"type":"object","properties":{"vars":{"type":"array","items":{"type":"string"}}},"required":["vars"]},"results":{"type":"object","properties":{"bindings":{"type":"array","items":{"type":"object"}}},"required":["bindings"]}},"required":["head","results"]},"source_url":{"type":"string","description":"Exact upstream request URL","minLength":1,"maxLength":20000},"notice":{"type":"string","description":"Source limitations","minLength":1,"maxLength":2000},"coverage":{"type":"object","properties":{"complete":{"type":"boolean"},"scope":{"type":"string","description":"Scope of the returned response","minLength":1,"maxLength":2000}},"required":["complete","scope"]}},"required":["data","source_url","notice","coverage"]}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
