1,"maxLength":20000},"notice":{"type":"string","description":"Source limitations","minLength":1,"maxLength":2000},"coverage":{"type":"object","properties":{"complete":{"type":"boolean"},"scope":{"type":"string","description":"Scope of the returned response","minLength":1,"maxLength":2000}},"required":["complete","scope"]}},"required":["data","source_url","notice","coverage"]}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;
